// next.config.ts: cacheComponents: true
import { Suspense } from 'react';
import { cookies } from 'next/headers';

export default function RestaurantePage() {
  return (
    <>
      {/* Casca estática: pré-renderizada no build e servida na hora */}
      <Cabecalho />
      <Cardapio /> {/* em cache ('use cache'), também entra na casca */}

      {/* Parte dinâmica: depende do cookie, chega por streaming na mesma resposta */}
      <Suspense fallback={<p>Carregando seu carrinho…</p>}>
        <Carrinho />
      </Suspense>
    </>
  );
}

async function Carrinho() {
  const sessao = (await cookies()).get('sessao')?.value; // dado da requisição
  const itens = await buscarCarrinho(sessao);
  return <ResumoDoCarrinho itens={itens} />;
}

import { cacheLife, cacheTag, updateTag } from 'next/cache';

// Mesmo resultado para todo mundo: guardado em cache por horas
export async function Cardapio() {
  'use cache';
  cacheLife('hours');
  cacheTag('cardapio');

  const pratos = await db.prato.findMany({ where: { disponivel: true } });
  return <ListaDePratos pratos={pratos} />;
}

// Server Action do painel do restaurante
export async function marcarEsgotado(pratoId: string) {
  'use server';
  await db.prato.update({ where: { id: pratoId }, data: { disponivel: false } });
  updateTag('cardapio'); // expira o cache: a próxima visita já vê o prato esgotado
}

import Image from 'next/image';
import capa from './capa-restaurante.jpg'; // import estático: largura, altura e blur automáticos

export function Destaque({ fotoDoPrato }: { fotoDoPrato: string }) {
  return (
    <>
      {/* Maior elemento acima da dobra: candidato a LCP, então pré-carrega */}
      <Image src={capa} alt="Salão do restaurante" preload placeholder="blur" sizes="100vw" />

      {/* Imagem remota: largura e altura reservam o espaço (sem CLS); sizes evita baixar a versão grande no celular */}
      <Image
        src={fotoDoPrato}
        alt="Pizza margherita"
        width={640}
        height={480}
        sizes="(max-width: 768px) 100vw, 50vw"
      />
    </>
  );
}

'use client';

import dynamic from 'next/dynamic';
import { useState } from 'react';

// O mapa (e a biblioteca dele) só é baixado quando a pessoa abre a seção
const MapaDeEntrega = dynamic(() => import('./MapaDeEntrega'), {
  loading: () => <p>Carregando mapa…</p>,
  ssr: false, // usa window: só renderiza no navegador (permitido em Client Components)
});

export function AreaDeEntrega() {
  const [aberto, setAberto] = useState(false);
  return (
    <section>
      <button onClick={() => setAberto(true)}>Ver área de entrega</button>
      {aberto && <MapaDeEntrega />}
    </section>
  );
}

