const enviar = (metric: { name: string; value: number; rating: string; id: string }) => {
  const body = JSON.stringify(metric);
  // sendBeacon continua funcionando quando a pessoa fecha a aba
  if (!navigator.sendBeacon?.('/api/vitals', body)) {
    fetch('/api/vitals', { method: 'POST', body, keepalive: true });
  }
};

export function WebVitals() {
  useReportWebVitals(enviar); // função estável, fora do componente
  return null;
}

