'use client';

import { useState, useTransition } from 'react';

export function BuscaDePratos({ pratos }: { pratos: Prato[] }) {
  const [texto, setTexto] = useState('');
  const [filtro, setFiltro] = useState('');
  const [pendente, startTransition] = useTransition();

  const visiveis = pratos.filter((p) => p.nome.toLowerCase().includes(filtro));

  return (
    <>
      <input
        value={texto}
        onChange={(e) => {
          setTexto(e.target.value); // urgente: o campo responde na hora
          startTransition(() => setFiltro(e.target.value.toLowerCase())); // pode esperar e ser interrompido
        }}
      />
      <ul style={{ opacity: pendente ? 0.6 : 1 }}>
        {visiveis.map((p) => <ItemDoCardapio key={p.id} prato={p} />)}
      </ul>
    </>
  );
}
